#!/usr/bin/env bash
# Generated by MiniMax M3.1 Flash without human creative authorship.
# SPDX-License-Identifier: LGPL-2.0-or-later
#
# Verify that an ARM64X forwarder routes exports to the right backend.
#
# An ARM64X DLL carries two export tables. A native ARM64 process must see
# the ARM64 backend's exports; an emulated x64 process must see the x64
# backend's. The check loads the forwarder from both an ARM64 and an x64
# process and reports which module each export actually resolved into.
#
# Usage: verify-forwarder.sh <forwarder.dll> <arm64-backend.dll> <x64-backend.dll>
set -euo pipefail
export MSYS_NO_PATHCONV=1

HERE="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
ROOT="$(cd "$HERE/../.." && pwd)"
TOOLS="$ROOT/.tools"
CC="$TOOLS/mingw64/bin/clang-cl.exe"
LL="$TOOLS/mingw64/bin/lld-link.exe"
SDK="$TOOLS/msvc"
PY="$ROOT/python/python3/python.exe"
WORK="$TOOLS/arm64x"

FWD="$1"
ARM64_DLL="$2"
X64_DLL="$3"

RUNTIME="$WORK/runtime"
rm -rf "$RUNTIME"
mkdir -p "$RUNTIME" "$WORK"
cp "$FWD" "$RUNTIME/PIMETextService.dll"
cp "$ARM64_DLL" "$RUNTIME/PIMETextService_arm64.dll"
cp "$X64_DLL" "$RUNTIME/PIMETextService_x64.dll"

SDK_W="$(cygpath -w "$SDK")"
INC="/I$SDK_W\\sdk\\include\\ucrt /I$SDK_W\\sdk\\include\\shared /I$SDK_W\\sdk\\include\\um /I$SDK_W\\crt\\include"
for arch in arm64 x64; do
  case $arch in
    arm64) target=aarch64-pc-windows-msvc ;;
    x64)   target=x86_64-pc-windows-msvc ;;
  esac
  "$CC" --target="$target" -c $INC \
    "-Fo$(cygpath -w "$WORK")\\loadone-$arch.obj" "$(cygpath -w "$HERE/loadone.c")"
  "$LL" -nologo "-out:$(cygpath -w "$WORK")\\loadone-$arch.exe" \
    "$(cygpath -w "$WORK")\\loadone-$arch.obj" \
    "/LIBPATH:$SDK_W\\crt\\lib\\$arch" "/LIBPATH:$SDK_W\\sdk\\lib\\ucrt\\$arch" \
    "/LIBPATH:$SDK_W\\sdk\\lib\\um\\$arch"
done

fail=0
for arch in arm64 x64; do
  case $arch in
    arm64) expect=PIMETextService_arm64 ;;
    x64)   expect=PIMETextService_x64 ;;
  esac
  out="$("$WORK/loadone-$arch.exe" "$(cygpath -w "$RUNTIME/PIMETextService.dll")" \
        DllGetClassObject 2>&1)" || true
  printf '  %-5s : %s\n' "$arch" "$(echo "$out" | tr '\n' ' ')"
  if echo "$out" | grep -q "in .*$expect"; then
    echo "         -> routed to $expect"
  else
    echo "         -> WRONG: expected $expect" >&2
    fail=1
  fi
done

echo
echo "=== ARM64X metadata ==="
"$PY" "$(cygpath -w "$HERE/meta.py")" "$(cygpath -w "$FWD")"

exit $fail
